let img; 
let mySize = 100;

let colors = ["#000000","#FFFFFF"];

function preload()
{
	img = loadImage("file:///Users/unclerm/Vibe Coding/4K MV Visual Integration Editor/assets_cache/guayaba_100x100.png");
}

function setBackground()
{
	fill(0);
	rect(width/2,height/2,width-100,height-100);
}

function setup() {
	createCanvas(n=mySize*10,n);
	colorMode(HSB, 360, 100, 100)
	rectMode(CENTER);
	imageMode(CENTER);
	frameRate(40);
  setBackground();
	// noLoop() removed for animation

}

function draw() {

	//randomSeed(123);
	setBackground();
	drawGrid(n/10);
}

function drawGrid(mySize)
{ 
	strokeWeight(8);
	for(let xx=mySize;xx <= width - mySize;xx+=(Math.max(0.001, Math.abs(mySize)) || 1))
	{
		for(let yy=mySize;yy <= height -mySize;yy+=(Math.max(0.001, Math.abs(mySize)) || 1))
		{
      for(let r = mySize;r > 0;r-=mySize/5)
			{
				stroke(generateColor(1));
			  rect(xx,yy,r,r);
			}
    }
	}

	for(let xx=mySize;xx <= width - mySize;xx+=(Math.max(0.001, Math.abs(mySize)) || 1))
	{
		for(let yy=mySize;yy <= height -mySize;yy+=(Math.max(0.001, Math.abs(mySize)) || 1))
		{
			noFill();
			//stroke(255);
			//strokeWeight(4);
      drawImage(xx,yy,1);
    }
	}
}

function drawImage(x,y,myScale)
{
	push();
	translate(x,y);
	scale(myScale,myScale);
	rotate(random([0,-PI/2]));
	//rotate(frameCount/200);
	image(img,0,0);
  pop();
}

function generateColor(scale) {
	let temp = color(colors[floor(random(0, colors.length))]);
	myColor = color(hue(window.color(temp)),
		saturation(window.color(temp)),
		brightness(window.color(temp)) + 100,
		random(1,1));
	return myColor;
}
